window.LEARNING_HUB_FUNDAMENTAL_ANALYSIS = [{"id":1,"category":"Finansal Tablolar ve Muhasebe Kalitesi","name":"Gelir Tablosu (Income Statement)","short":"Gelir Tablosu","definition":"Belirli bir dönemde hasılat, maliyet, faaliyet giderleri, finansman, vergi ve net kârın nasıl oluştuğunu gösterir.","formula":"Hasılat − Satışların Maliyeti = Brüt Kâr; Brüt Kâr − Faaliyet Giderleri = EBIT; vergi/finansman sonrası = Net Kâr.","interpretation":"Tek dönemden çok 3–5 yıllık satış, marj ve kâr trendine bakılır.","bands":[{"label":"İyi","text":"Satış ve faaliyet kârı birlikte büyüyor; marjlar stabil/artan."},{"label":"Uyarı","text":"Satış büyürken marj/kâr düşüyor veya kâr tek seferlik gelirlerden oluşuyor."}],"advantages":["Kârlılığın kaynağını gösterir","Marj analizi sağlar"],"disadvantages":["Nakit yaratımıyla aynı değildir","Tahmin ve sınıflamalardan etkilenir"],"suitable":"Tüm şirketler","caveat":"Net kârı nakit akışı ve bilanço ile teyit et.","related":["Brüt Marj","EBIT Marjı","Net Marj","CFO/Net Kâr"],"source":"SEC / IFRS","kind":"Statement","rank":1},{"id":2,"category":"Finansal Tablolar ve Muhasebe Kalitesi","name":"Bilanço (Balance Sheet)","short":"Bilanço","definition":"Belirli bir tarihte varlıkları, yükümlülükleri ve özkaynağı gösterir.","formula":"Varlıklar = Yükümlülükler + Özkaynak.","interpretation":"Likidite, borçluluk, varlık kalitesi, özkaynak ve işletme sermayesi birlikte analiz edilir.","bands":[{"label":"İyi","text":"Likidite yeterli, vade profili dengeli, özkaynak kaliteli."},{"label":"Uyarı","text":"Kısa vadeli borç yoğunluğu, negatif özkaynak, yüksek goodwill veya zayıf nakit tamponu."}],"advantages":["Finansal dayanıklılığı gösterir"],"disadvantages":["Defter değerleri piyasa değerinden farklı olabilir"],"suitable":"Tüm şirketler","caveat":"Bilanço dışı yükümlülükler ve dipnotlar da incelenmelidir.","related":["Net Borç/FAVÖK","Cari Oran","PD/DD"],"source":"SEC / IFRS","kind":"Statement","rank":2},{"id":3,"category":"Finansal Tablolar ve Muhasebe Kalitesi","name":"Nakit Akış Tablosu (Cash Flow Statement)","short":"Nakit Akış Tablosu","definition":"Nakit hareketlerini faaliyet, yatırım ve finansman faaliyetleri olarak sınıflandırır.","formula":"Net Nakit Değişimi = CFO + CFI + CFF.","interpretation":"Kârın gerçekten nakde dönüşüp dönüşmediğini ve büyümenin nasıl finanse edildiğini gösterir.","bands":[{"label":"İyi","text":"CFO pozitif ve kalıcı; FCF zamanla büyüyor."},{"label":"Uyarı","text":"Net kâr pozitifken CFO kalıcı negatif."}],"advantages":["Kâr kalitesini test eder","Borç/temettü kapasitesini gösterir"],"disadvantages":["Working-capital tek dönemi bozabilir"],"suitable":"Tüm şirketler","caveat":"IAS 7 kapsamında faaliyet, yatırım ve finansman akımlarını ayrı değerlendir.","related":["CFO/Net Kâr","FCF","Capex"],"source":"IFRS IAS 7 / SEC","kind":"Statement","rank":3},{"id":4,"category":"Finansal Tablolar ve Muhasebe Kalitesi","name":"Dipnotlar ve Muhasebe Politikaları","short":"Dipnot Analizi","definition":"Gelir tanıma, stok, amortisman, karşılık, leasing, dava ve ilişkili taraf detaylarını açıklar.","formula":"Formül yok; açıklama ve mutabakat analizi.","interpretation":"Sık politika değişimi veya agresif gelir tanıma muhasebe kalitesi açısından uyarıdır.","bands":[{"label":"İyi","text":"Tutarlı ve şeffaf politikalar."},{"label":"Uyarı","text":"Sık yöntem değişimi, yoğun ilişkili taraf, sürekli tek seferlik düzeltme."}],"advantages":["Gizli riskleri ortaya çıkarır"],"disadvantages":["Zaman alıcı ve yorum gerektirir"],"suitable":"Tüm şirketler","caveat":"Non-GAAP metrikler şirketler arasında standart değildir.","related":["Accrual Ratio","Beneish M","CFO/Net Kâr"],"source":"SEC / IFRS","kind":"Quality","rank":4},{"id":5,"category":"Finansal Tablolar ve Muhasebe Kalitesi","name":"Non-GAAP / Düzeltilmiş Kâr","short":"Adjusted Earnings","definition":"Yönetimin GAAP/IFRS dışı düzeltmelerle sunduğu EBITDA/EPS gibi ölçülerin kalitesini inceler.","formula":"Raporlanan sonuç ± yönetim düzeltmeleri.","interpretation":"Gerçekten nadir kalemlerin ayıklanması faydalıdır; her yıl tekrarlanan “tek seferlik” giderler uyarıdır.","bands":[{"label":"İyi","text":"Sınırlı ve açık mutabakatlı düzeltmeler."},{"label":"Uyarı","text":"SBC, restructuring veya acquisition giderleri sürekli dışlanıyor."}],"advantages":["Operasyonel trendi temizleyebilir"],"disadvantages":["Karşılaştırılabilirlik zayıf","Kârı aşırı iyimser gösterebilir"],"suitable":"Teknoloji, M&A yoğun şirketler","caveat":"SEC, uygun etiket/açıklama olmadan non-GAAP ölçülerin yanıltıcı olabileceğini vurgular.","related":["EBITDA","FCF","CFO/Net Kâr"],"source":"SEC","kind":"Quality","rank":5},{"id":6,"category":"Kârlılık ve Sermaye Verimliliği","name":"Brüt Kâr Marjı (Gross Margin)","short":"Brüt Marj","definition":"Doğrudan ürün/hizmet maliyetleri sonrası satışlardan kalan paydır.","formula":"Brüt Kâr / Hasılat × 100","interpretation":"Yükseliş fiyatlama gücü, ürün karması veya maliyet avantajı gösterebilir.","bands":[{"label":"İyi","text":"Sektör medyanının üzerinde ve stabil/artan."},{"label":"Uyarı","text":"3–5 yıldır düşen marj."}],"advantages":["Fiyatlama gücünü gösterir"],"disadvantages":["Sektörler arası mutlak kıyas uygun değildir"],"suitable":"Üretim, perakende, yazılım","caveat":"SaaS ile perakende aynı eşikle değerlendirilemez.","related":["EBITDA Marjı","EBIT Marjı"],"source":"SEC","kind":"Metric","rank":6},{"id":7,"category":"Kârlılık ve Sermaye Verimliliği","name":"FAVÖK Marjı (EBITDA Margin)","short":"FAVÖK Marjı","definition":"Faiz, vergi, amortisman ve itfa öncesi kârın satışlara oranıdır.","formula":"EBITDA / Hasılat × 100","interpretation":"Faaliyet ölçeklenebilirliği ve borç servis kapasitesi hakkında hızlı fikir verir.","bands":[{"label":"Genel Güçlü","text":"%15–20+ birçok sektörde güçlü başlangıç; sektör şart."},{"label":"Uyarı","text":"Tek haneli ve düşen marj."}],"advantages":["Sermaye yapısından kısmen arındırır"],"disadvantages":["Capex ihtiyacını görmez","IFRS 16 etkisi olabilir"],"suitable":"Sanayi, telekom, hizmet","caveat":"Bankalarda ana metric değildir.","related":["EV/EBITDA","FCF Marjı"],"source":"Damodaran / Finansal tablolar","kind":"Metric","rank":7},{"id":8,"category":"Kârlılık ve Sermaye Verimliliği","name":"Faaliyet Kâr Marjı (EBIT Margin)","short":"EBIT Marjı","definition":"Amortisman sonrası çekirdek faaliyet kârının satışlara oranıdır.","formula":"EBIT / Hasılat × 100","interpretation":"Operasyonel kârlılığı sermaye yapısından arındırır.","bands":[{"label":"Güçlü","text":"%15+ birçok sektör için güçlü başlangıç."},{"label":"İnce","text":"%0–5 düşük tampon."}],"advantages":["Amortismanı içerir"],"disadvantages":["Sermaye yoğunluğu sektöre bağlı"],"suitable":"Çoğu sanayi/hizmet şirketi","caveat":"Cycle peak marjlarına dikkat.","related":["ROIC","EV/EBIT"],"source":"Damodaran","kind":"Metric","rank":8},{"id":9,"category":"Kârlılık ve Sermaye Verimliliği","name":"Net Kâr Marjı (Net Margin)","short":"Net Marj","definition":"Tüm giderler sonrası net kârın satışlara oranıdır.","formula":"Net Kâr / Hasılat × 100","interpretation":"Satış başına nihai kâr kapasitesini ölçer.","bands":[{"label":"İyi","text":"%10+ genel başlangıç."},{"label":"Çok Güçlü","text":"%20+; sektör bağımlı."},{"label":"İnce","text":"%0–5."}],"advantages":["Basit ve anlaşılır"],"disadvantages":["Faiz/vergi/tek seferlik kalemlerden etkilenir"],"suitable":"Çoğu şirket","caveat":"Bankalarda sektör özel oranlarla birlikte kullan.","related":["EBIT Marjı","ROE"],"source":"SEC","kind":"Metric","rank":9},{"id":10,"category":"Kârlılık ve Sermaye Verimliliği","name":"ROE – Özkaynak Kârlılığı","short":"ROE","definition":"Hissedar özkaynağı üzerinden yaratılan net kârı ölçer.","formula":"Net Kâr / Ortalama Özkaynak × 100","interpretation":"Yüksek ve sürdürülebilir ROE kalite göstergesi olabilir; leverage ile şişebilir.","bands":[{"label":"Güçlü","text":"%15+"},{"label":"Makul","text":"%10–15"},{"label":"Zayıf","text":"<%8"},{"label":"Uyarı","text":"Negatif özkaynakta anlamsız."}],"advantages":["Hissedar sermaye verimliliği","Bankalarda çok önemli"],"disadvantages":["Borçla yapay yükselebilir"],"suitable":"Bankalar, sigorta, olgun şirketler","caveat":"DuPont ve borçlulukla birlikte bak.","related":["ROIC","DuPont","P/B"],"source":"SEC / DuPont","kind":"Metric","rank":10},{"id":11,"category":"Kârlılık ve Sermaye Verimliliği","name":"ROA – Aktif Kârlılığı","short":"ROA","definition":"Toplam varlıkların ne kadar net kâr ürettiğini ölçer.","formula":"Net Kâr / Ortalama Toplam Varlıklar × 100","interpretation":"Varlık yoğun sektörlerde sermaye verimliliğini gösterir.","bands":[{"label":"Sanayi","text":"%5+ çoğu zaman iyi başlangıç."},{"label":"Bankalar","text":"%1–2 bankalarda güçlü olabilir."}],"advantages":["Kaldıraç etkisi ROE’den düşük"],"disadvantages":["Asset-light ve asset-heavy kıyaslanamaz"],"suitable":"Bankalar, sanayi","caveat":"Goodwill/yeniden değerleme aktif tabanını etkileyebilir.","related":["ROE","Asset Turnover"],"source":"SEC","kind":"Metric","rank":11},{"id":12,"category":"Kârlılık ve Sermaye Verimliliği","name":"ROIC – Yatırılan Sermaye Getirisi","short":"ROIC","definition":"Operasyonların yatırılan borç+özkaynak sermayeden yarattığı vergi sonrası getiridir.","formula":"NOPAT / Ortalama Invested Capital; NOPAT ≈ EBIT×(1−T)","interpretation":"En kritik soru ROIC’in WACC üzerinde olup olmadığıdır.","bands":[{"label":"Değer Yaratıyor","text":"ROIC > WACC."},{"label":"İyi Spread","text":"ROIC − WACC ≥ 3 puan."},{"label":"Çok Güçlü","text":"Spread ≥ 5 puan."},{"label":"Değer Yok Ediyor","text":"ROIC < WACC."}],"advantages":["Ekonomik değer yaratımını doğrudan ölçer"],"disadvantages":["Invested capital ayarı gerekir"],"suitable":"Sermaye yoğun ve olgun şirketler","caveat":"Cycle-average ROIC kullan.","related":["WACC","EVA","FCF"],"source":"Damodaran","kind":"Metric","rank":12},{"id":13,"category":"Kârlılık ve Sermaye Verimliliği","name":"ROCE – Kullanılan Sermaye Getirisi","short":"ROCE","definition":"Faaliyet kârının uzun vadeli kullanılan sermayeye göre verimliliğidir.","formula":"EBIT / (Toplam Varlıklar − Kısa Vadeli Yükümlülükler)","interpretation":"ROCE’nin sermaye maliyeti üzerinde kalması olumlu.","bands":[{"label":"İyi","text":"WACC üzerinde ve stabil."},{"label":"Uyarı","text":"WACC altında veya düşen."}],"advantages":["Sermaye yoğun şirketlerde faydalı"],"disadvantages":["Tanımlar farklılaşabilir"],"suitable":"Sanayi, enerji, altyapı","caveat":"ROIC ile aynı şey değildir.","related":["ROIC","WACC"],"source":"Corporate Finance","kind":"Metric","rank":13},{"id":14,"category":"Kârlılık ve Sermaye Verimliliği","name":"DuPont Analizi","short":"DuPont","definition":"ROE’yi marj, varlık devir hızı ve finansal kaldıraç bileşenlerine ayırır.","formula":"ROE = Net Marj × Asset Turnover × Equity Multiplier","interpretation":"ROE artışının operasyon mu borç mu kaynaklı olduğunu gösterir.","bands":[{"label":"Kaliteli ROE","text":"Marj ve varlık verimliliği kaynaklı."},{"label":"Riskli ROE","text":"Esasen kaldıraç artışından kaynaklı."}],"advantages":["ROE’nin kaynağını açıklar"],"disadvantages":["Muhasebe kalemlerine bağlı"],"suitable":"Finansal olmayan şirketler","caveat":"Finansallarda leverage doğal olarak yüksektir.","related":["ROE","Debt/Equity","Asset Turnover"],"source":"DuPont","kind":"Metric","rank":14},{"id":15,"category":"Kârlılık ve Sermaye Verimliliği","name":"Brüt Kâr / Varlıklar","short":"Gross Profitability","definition":"Brüt kârın toplam varlıklara oranıdır.","formula":"Gross Profit / Total Assets","interpretation":"Varlık başına brüt ekonomik üretim kapasitesini ölçer.","bands":[{"label":"Yorum","text":"Sektör ve tarihsel dağılıma göre yüksek olması olumlu."}],"advantages":["Kalite factor screening’de yararlı"],"disadvantages":["Sektörler arası yapısal fark yüksek"],"suitable":"Fundamental factor screening","caveat":"Tek başına değerleme sinyali değildir.","related":["Gross Margin","ROA"],"source":"Factor analysis","kind":"Metric","rank":15},{"id":16,"category":"Büyüme ve Operasyonel Momentum","name":"Hasılat Büyümesi","short":"Revenue Growth","definition":"Satışların dönemler arasında büyüme hızıdır.","formula":"(Cari Hasılat / Önceki Hasılat − 1) × 100","interpretation":"Fiyat, hacim, M&A ve FX katkısı ayrıştırılmalıdır.","bands":[{"label":"İyi","text":"Reel olarak pozitif, sektör üzerinde ve marjla birlikte."},{"label":"Uyarı","text":"Satış büyürken marj/FCF düşüyor."}],"advantages":["İş ölçeğini gösterir"],"disadvantages":["Enflasyon ve M&A nominal büyümeyi şişirebilir"],"suitable":"Tüm şirketler","caveat":"Yüksek enflasyonda reel büyüme hesapla.","related":["Organic Growth","EPS Growth"],"source":"Finansal tablolar","kind":"Metric","rank":16},{"id":17,"category":"Büyüme ve Operasyonel Momentum","name":"Organik Büyüme","short":"Organic Growth","definition":"M&A, kur ve portföy değişimleri temizlenmiş çekirdek büyümedir.","formula":"Raporlanan büyüme − M&A etkisi − FX etkisi ± portföy değişimi","interpretation":"Çekirdek talep ve fiyatlama gücünü daha temiz gösterir.","bands":[{"label":"Güçlü","text":"Pozitif ve sektör üzerinde."},{"label":"Uyarı","text":"Toplam büyümenin çoğu satın almadan geliyor."}],"advantages":["Gerçek iş momentumunu gösterir"],"disadvantages":["Şirket tanımları farklı olabilir"],"suitable":"M&A yapan şirketler","caveat":"Şirketin organik büyüme tanımını kontrol et.","related":["Revenue Growth","Pricing"],"source":"Company disclosures","kind":"Metric","rank":17},{"id":18,"category":"Büyüme ve Operasyonel Momentum","name":"EPS Büyümesi","short":"EPS Growth","definition":"Hisse başına kârın büyüme hızıdır.","formula":"Cari EPS / Önceki EPS − 1","interpretation":"Hisse başına değer yaratımını gösterir.","bands":[{"label":"Güçlü","text":"Sürdürülebilir çift haneli + nakit dönüşümü."},{"label":"Uyarı","text":"Sadece buyback veya tek seferlik gelir kaynaklı."}],"advantages":["Hissedar perspektifinde doğrudan"],"disadvantages":["Buyback ile yapay artırılabilir"],"suitable":"Kârlı şirketler","caveat":"Diluted share count değişimini kontrol et.","related":["Share Count","CFO/Net Kâr"],"source":"Financial statements","kind":"Metric","rank":18},{"id":19,"category":"Büyüme ve Operasyonel Momentum","name":"FCF Büyümesi","short":"FCF Growth","definition":"Serbest nakit akımının büyüme hızıdır.","formula":"FCF = CFO − Capex; büyüme = Cari FCF / Önceki FCF − 1","interpretation":"Uzun vadede kâr büyümesinin nakde dönüşmesini test eder.","bands":[{"label":"Güçlü","text":"3–5 yıllık FCF CAGR pozitif ve EPS ile uyumlu."},{"label":"Uyarı","text":"EPS büyürken FCF kalıcı geriliyor."}],"advantages":["Nakit bazlı growth"],"disadvantages":["Capex döngüsü oynaklık yaratır"],"suitable":"Nakit üreten şirketler","caveat":"Growth capex ve maintenance capex ayrımı önemli.","related":["FCF Yield","CFO/Net Kâr"],"source":"Damodaran","kind":"Metric","rank":19},{"id":20,"category":"Büyüme ve Operasyonel Momentum","name":"CAGR – Bileşik Yıllık Büyüme","short":"CAGR","definition":"Başlangıç ve bitiş değeri arasındaki bileşik yıllık büyümeyi ölçer.","formula":"(Bitiş/Başlangıç)^(1/n) − 1","interpretation":"3–5 yıllık satış, EPS, FCF ve özkaynak trendinde kullanılır.","bands":[{"label":"Kullanım","text":"Tek yıllık büyüme yerine 3–5 yıl CAGR daha sağlam."}],"advantages":["Kolay karşılaştırma"],"disadvantages":["Ara yıllardaki volatiliteyi gizler"],"suitable":"Tüm şirketler","caveat":"Başlangıç/bitiş anormalse yanıltıcı olabilir.","related":["Revenue Growth","EPS Growth"],"source":"Matematik","kind":"Metric","rank":20},{"id":21,"category":"Değerleme Çarpanları","name":"F/K – P/E (Price / Earnings)","short":"P/E","definition":"Hisse fiyatının hisse başına kâra kaç kat ödendiğini gösterir.","formula":"Hisse Fiyatı / EPS = Piyasa Değeri / Net Kâr","interpretation":"Düşük P/E ucuzluk veya düşük kalite; yüksek P/E büyüme/kalite primi veya aşırı fiyatlama olabilir.","bands":[{"label":"Düşük","text":"<10x"},{"label":"Orta","text":"10–20x"},{"label":"Primli","text":"20–30x"},{"label":"Yüksek","text":">30x; güçlü büyüme gerekir."}],"advantages":["En yaygın çarpan"],"disadvantages":["Negatif kârda kullanılamaz","Borcu görmez"],"suitable":"Kârlı şirketler","caveat":"Faiz, büyüme ve ROE haklı P/E’yi değiştirir.","related":["PEG","Earnings Yield","FCF Yield"],"source":"SEC / Damodaran","kind":"Metric","rank":21},{"id":22,"category":"Değerleme Çarpanları","name":"PEG – P/E / Growth","short":"PEG","definition":"P/E çarpanını beklenen EPS büyümesine göre normalize eder.","formula":"P/E / Beklenen EPS Growth (%)","interpretation":"Yaklaşık 1x büyüme ile fiyatlamanın dengeli olduğuna dair başlangıç noktasıdır.","bands":[{"label":"Potansiyel Ucuz","text":"<1x"},{"label":"Dengeli","text":"1–2x"},{"label":"Pahalı","text":">2x; kalite/growth çok güçlü değilse."}],"advantages":["Growth hisselerinde yararlı"],"disadvantages":["Forecast growth’a aşırı hassas"],"suitable":"Kârlı büyüme şirketleri","caveat":"Büyümenin sermaye ihtiyacını görmez.","related":["P/E","EPS Growth","ROIC"],"source":"Valuation framework","kind":"Metric","rank":22},{"id":23,"category":"Değerleme Çarpanları","name":"PD/DD – P/B (Price / Book)","short":"P/B","definition":"Piyasa değerinin muhasebe özkaynağına oranıdır.","formula":"Piyasa Değeri / Özkaynak","interpretation":"Özellikle banka ve varlık yoğun şirketlerde anlamlıdır; ROE ve cost of equity ile birlikte yorumlanır.","bands":[{"label":"<1x","text":"Ucuz veya varlık kalitesi/ROE endişesi."},{"label":"1–3x","text":"Birçok kaliteli varlık/finansal şirkette normal band."},{"label":">3x","text":"Yüksek ROE/büyüme primi gerekir."}],"advantages":["Bankalarda çok kullanışlı"],"disadvantages":["Asset-light şirketlerde book value zayıf proxy"],"suitable":"Bankalar, sigorta, holding, sanayi","caveat":"P/B tek başına değil ROE ile okunmalı.","related":["ROE","P/TBV","NAV"],"source":"SEC / Damodaran","kind":"Metric","rank":23},{"id":24,"category":"Değerleme Çarpanları","name":"P/TBV – Fiyat / Maddi Defter Değeri","short":"P/TBV","definition":"Goodwill ve intangible varlıklar çıkarılmış özkaynağa göre fiyatlamadır.","formula":"Piyasa Değeri / Tangible Common Equity","interpretation":"Özellikle bankalarda daha temiz book-value kıyası sağlar.","bands":[{"label":"<1x","text":"Varlık kalitesi/kârlılık endişesi olabilir."},{"label":"1–2x","text":"ROTCE güçlü ise makul."},{"label":">2x","text":"Yüksek ROTCE/kalite gerekir."}],"advantages":["Goodwill etkisini temizler"],"disadvantages":["Intangible ekonomik değeri sıfırlar"],"suitable":"Bankalar, finansallar","caveat":"ROTCE ile birlikte kullan.","related":["P/B","ROTCE"],"source":"Bank valuation","kind":"Metric","rank":24},{"id":25,"category":"Değerleme Çarpanları","name":"F/S – P/S (Price / Sales)","short":"P/S","definition":"Piyasa değerinin satışlara oranıdır.","formula":"Piyasa Değeri / Hasılat","interpretation":"Kâr etmeyen şirketlerde kullanılabilir; marjla birlikte yorumlanmalıdır.","bands":[{"label":"Düşük","text":"<2x"},{"label":"Primli","text":"2–5x"},{"label":"Yüksek","text":">5x; yüksek marj/growth gerekir."}],"advantages":["Negatif kârda kullanılabilir"],"disadvantages":["Marj ve borcu görmez"],"suitable":"Erken büyüme, SaaS","caveat":"%10 marjlı ve %40 marjlı şirket aynı P/S ile eşit değildir.","related":["EV/Sales","Gross Margin"],"source":"Damodaran","kind":"Metric","rank":25},{"id":26,"category":"Değerleme Çarpanları","name":"FD/FAVÖK – EV/EBITDA","short":"EV/EBITDA","definition":"Enterprise value’nun EBITDA’ya oranıdır.","formula":"EV = Market Cap + Net Debt + Minority − Non-operating assets; EV/EBITDA = EV / EBITDA","interpretation":"Borç yapısı farklı şirketleri operasyonel kâr üzerinden karşılaştırır.","bands":[{"label":"Düşük","text":"<8x"},{"label":"Orta","text":"8–12x"},{"label":"Primli","text":"12–18x"},{"label":"Yüksek","text":">18x; güçlü büyüme gerekir."}],"advantages":["Borcu içerir","M&A’da yaygın"],"disadvantages":["Capex’i görmez","IFRS 16 etkisi olabilir"],"suitable":"Sanayi, telekom, hizmet","caveat":"Bankalarda kullanılmaz; capex yoğun işte EV/EBIT ile teyit et.","related":["EV/EBIT","FCF Yield","Net Debt/EBITDA"],"source":"Damodaran","kind":"Metric","rank":26},{"id":27,"category":"Değerleme Çarpanları","name":"FD/Faaliyet Kârı – EV/EBIT","short":"EV/EBIT","definition":"Enterprise value’nun amortisman sonrası faaliyet kârına oranıdır.","formula":"EV / EBIT","interpretation":"Sermaye yoğun sektörlerde EBITDA’dan daha ekonomik olabilir.","bands":[{"label":"Düşük","text":"<10x"},{"label":"Orta","text":"10–15x"},{"label":"Primli","text":"15–20x"},{"label":"Yüksek","text":">20x."}],"advantages":["Amortismanı dikkate alır"],"disadvantages":["Cycle peak EBIT ucuzluk yanılsaması yaratabilir"],"suitable":"Sanayi, üretim","caveat":"Normalize EBIT kullan.","related":["EV/EBITDA","ROIC"],"source":"Damodaran","kind":"Metric","rank":27},{"id":28,"category":"Değerleme Çarpanları","name":"FD/Satışlar – EV/Sales","short":"EV/Sales","definition":"Enterprise value’nun satışlara oranıdır.","formula":"EV / Revenue","interpretation":"Negatif kârlı fakat büyüyen şirketleri borcu da dikkate alarak karşılaştırır.","bands":[{"label":"Düşük","text":"<2x"},{"label":"Primli","text":"2–5x"},{"label":"Yüksek","text":">5x."}],"advantages":["Negatif kârda çalışır","Borcu içerir"],"disadvantages":["Marjı doğrudan görmez"],"suitable":"SaaS, erken growth","caveat":"Gross margin ve FCF ile birlikte bak.","related":["P/S","Rule of 40"],"source":"Damodaran","kind":"Metric","rank":28},{"id":29,"category":"Değerleme Çarpanları","name":"FCF Yield – Serbest Nakit Akımı Getirisi","short":"FCF Yield","definition":"FCF’yi piyasa değerine oranlayarak nakit kazanç verimini ölçer.","formula":"FCF / Piyasa Değeri × 100","interpretation":"Yüksek FCF yield genelde daha düşük fiyatlama demektir.","bands":[{"label":"Cazip","text":">5–6% olgun şirkette güçlü başlangıç."},{"label":"Orta","text":"3–5%"},{"label":"Düşük","text":"<2–3%; büyüme çok güçlü değilse."}],"advantages":["Nakit bazlı değerleme"],"disadvantages":["Capex döngüsüne duyarlı"],"suitable":"Olgun şirketler","caveat":"Normalize FCF kullan.","related":["P/FCF","EV/FCF"],"source":"Damodaran","kind":"Metric","rank":29},{"id":30,"category":"Değerleme Çarpanları","name":"P/FCF – Fiyat / Serbest Nakit Akımı","short":"P/FCF","definition":"Piyasa değerinin FCF’ye kaç kat ödendiğini gösterir.","formula":"Piyasa Değeri / FCF","interpretation":"P/E’nin nakit bazlı alternatifidir.","bands":[{"label":"Düşük","text":"<15x"},{"label":"Orta","text":"15–25x"},{"label":"Yüksek","text":">25x."}],"advantages":["Nakit bazlı"],"disadvantages":["Negatif FCF’de kullanışsız"],"suitable":"Nakit üreten şirketler","caveat":"Growth capex geçici olarak FCF’yi düşürebilir.","related":["FCF Yield","P/E"],"source":"Valuation","kind":"Metric","rank":30},{"id":31,"category":"Değerleme Çarpanları","name":"EV / FCF","short":"EV/FCF","definition":"Enterprise value’yu firmaya ait FCF’ye oranlar.","formula":"EV / FCFF","interpretation":"Borç dahil işletme değerini nakit üretimine bağlar.","bands":[{"label":"Düşük","text":"<15x"},{"label":"Orta","text":"15–25x"},{"label":"Yüksek","text":">25x."}],"advantages":["Borcu içerir"],"disadvantages":["FCFF/capex oynaklığına hassas"],"suitable":"Finansal olmayan şirketler","caveat":"Normalize FCFF kullan.","related":["EV/EBITDA","FCF Yield"],"source":"Valuation","kind":"Metric","rank":31},{"id":32,"category":"Değerleme Çarpanları","name":"Earnings Yield – Kazanç Getirisi","short":"Earnings Yield","definition":"P/E’nin tersidir; piyasa değeri başına yıllık kârı gösterir.","formula":"1 / P/E = EPS / Fiyat","interpretation":"Risk-free yield ile karşılaştırılabilir.","bands":[{"label":"Yüksek","text":"%8–10+"},{"label":"Orta","text":"%5–8"},{"label":"Düşük","text":"<%3–4; yüksek valuation."}],"advantages":["Faizle kıyas kolay"],"disadvantages":["Kâr kalitesine bağlı"],"suitable":"Kârlı şirketler","caveat":"Nominal faiz rejimi bandın anlamını değiştirir.","related":["P/E","FCF Yield"],"source":"Valuation","kind":"Metric","rank":32},{"id":33,"category":"Değerleme Çarpanları","name":"Temettü Verimi","short":"Dividend Yield","definition":"Yıllık temettünün hisse fiyatına oranıdır.","formula":"DPS / Hisse Fiyatı × 100","interpretation":"Yüksek yield cazip olabilir fakat dividend trap riski vardır.","bands":[{"label":"Genel","text":"%2–5 birçok olgun pazarda normal."},{"label":"Uyarı","text":"Aşırı yüksek yield varsa payout/FCF/borç kontrol et."}],"advantages":["Nakit hissedar getirisi"],"disadvantages":["Growth ve buyback’i görmez"],"suitable":"Temettü şirketleri","caveat":"Payout ve FCF coverage ile teyit et.","related":["Payout Ratio","FCF"],"source":"Dividend analysis","kind":"Metric","rank":33},{"id":34,"category":"Borçluluk, Likidite ve Finansal Dayanıklılık","name":"Borç / Özkaynak","short":"D/E","definition":"Finansal borcun özkaynağa oranıdır.","formula":"Toplam Finansal Borç / Özkaynak","interpretation":"Yükseldikçe finansal kaldıraç ve faiz riski artar.","bands":[{"label":"Muhafazakâr","text":"<0.5x"},{"label":"Makul","text":"0.5–1x"},{"label":"Yüksek","text":"1–2x"},{"label":"Çok Yüksek","text":">2x; finansal olmayanlarda dikkat."}],"advantages":["Basit leverage ölçüsü"],"disadvantages":["Bankalarda doğal yüksek","Negatif equity’de anlamsız"],"suitable":"Finansal olmayan şirketler","caveat":"Net debt ve interest coverage ile birlikte bak.","related":["Net Debt/EBITDA","Interest Coverage"],"source":"SEC","kind":"Metric","rank":34},{"id":35,"category":"Borçluluk, Likidite ve Finansal Dayanıklılık","name":"Net Borç / FAVÖK","short":"Net Debt/EBITDA","definition":"Net borcun EBITDA’ya oranıdır.","formula":"(Finansal Borç − Nakit) / EBITDA","interpretation":"Borç geri ödeme/refinansman kapasitesi için yaygın kredi metriğidir.","bands":[{"label":"Çok Güçlü","text":"<1x"},{"label":"Sağlıklı","text":"1–2x"},{"label":"İzle","text":"2–3x"},{"label":"Yüksek","text":"3–4x"},{"label":"Stresli","text":">4x."}],"advantages":["Kredi analizinde çok yaygın"],"disadvantages":["EBITDA nakit değildir"],"suitable":"Sanayi, telekom, enerji","caveat":"Bankalarda kullanılmaz.","related":["Interest Coverage","Debt Maturity"],"source":"Credit analysis","kind":"Metric","rank":35},{"id":36,"category":"Borçluluk, Likidite ve Finansal Dayanıklılık","name":"Faiz Karşılama Oranı","short":"Interest Coverage","definition":"Faaliyet kârının faiz giderini kaç kez karşıladığını ölçer.","formula":"EBIT / Net Faiz Gideri (veya EBITDA/Faiz)","interpretation":"Düşük oran faiz ve refinansman riskini artırır.","bands":[{"label":"Güçlü","text":">5x"},{"label":"Yeterli","text":"3–5x"},{"label":"Zayıf","text":"1.5–3x"},{"label":"Riskli","text":"<1.5x."}],"advantages":["Borç servis riskini gösterir"],"disadvantages":["Hedge/faiz geliri etkiler"],"suitable":"Borçlu şirketler","caveat":"Floating-rate borç ve vade duvarı ile birlikte bak.","related":["Net Debt/EBITDA","FCF"],"source":"Credit analysis","kind":"Metric","rank":36},{"id":37,"category":"Borçluluk, Likidite ve Finansal Dayanıklılık","name":"Cari Oran","short":"Current Ratio","definition":"Dönen varlıkların kısa vadeli yükümlülüklere oranıdır.","formula":"Dönen Varlıklar / Kısa Vadeli Yükümlülükler","interpretation":"1 altı likidite baskısı; aşırı yüksek oran atıl working capital olabilir.","bands":[{"label":"Sağlıklı","text":"1.2–2.0x"},{"label":"Risk","text":"<1x"},{"label":"Aşırı","text":">3x bazı sektörlerde verimsiz."}],"advantages":["Basit likidite göstergesi"],"disadvantages":["Stok kalitesini ayırmaz"],"suitable":"Sanayi, perakende","caveat":"Negatif working-capital modellerinde düşük oran normal olabilir.","related":["Quick Ratio","CCC"],"source":"SEC","kind":"Metric","rank":37},{"id":38,"category":"Borçluluk, Likidite ve Finansal Dayanıklılık","name":"Asit-Test / Quick Ratio","short":"Quick Ratio","definition":"Stokları dışarıda bırakan sıkı likidite ölçüsüdür.","formula":"(Nakit + Menkul + Alacaklar) / Kısa Vadeli Yükümlülükler","interpretation":"1x civarı ve üzeri çoğu şirkette rahatlık sağlar.","bands":[{"label":"Güçlü","text":">1x"},{"label":"İzle","text":"0.7–1x"},{"label":"Risk","text":"<0.7x."}],"advantages":["Stok riskini temizler"],"disadvantages":["Alacak kalitesini varsayar"],"suitable":"Sanayi, dağıtım","caveat":"DSO yükseliyorsa alacaklar likit olmayabilir.","related":["Current Ratio","DSO"],"source":"SEC","kind":"Metric","rank":38},{"id":39,"category":"Borçluluk, Likidite ve Finansal Dayanıklılık","name":"Nakit Oranı","short":"Cash Ratio","definition":"Sadece nakitle kısa vadeli borçların karşılanma gücüdür.","formula":"Nakit / Kısa Vadeli Yükümlülükler","interpretation":"Yüksek oran güçlü tampon; aşırı nakit sermaye verimsizliği olabilir.","bands":[{"label":"Güçlü","text":"0.5x+ başlangıç."},{"label":"Düşük","text":"<0.2x; business model’e göre."}],"advantages":["Konservatif likidite ölçüsü"],"disadvantages":["Operasyonel nakit dönüşümünü görmez"],"suitable":"Likidite hassas şirketler","caveat":"Sektörün working-capital modeli önemlidir.","related":["Quick Ratio","CFO"],"source":"Liquidity analysis","kind":"Metric","rank":39},{"id":40,"category":"Borçluluk, Likidite ve Finansal Dayanıklılık","name":"Borç Vade Profili","short":"Debt Maturity","definition":"Borç anapara/kupon ödemelerinin yıllara dağılımıdır.","formula":"Formül yok; yıllık maturity schedule.","interpretation":"Yakın vadeli büyük maturity wall yüksek faiz döneminde risk yaratır.","bands":[{"label":"İyi","text":"Vade dengeli; likidite + FCF yakın ödemeleri karşılıyor."},{"label":"Uyarı","text":"12–24 ayda yoğun geri ödeme."}],"advantages":["Refinansman riskini gerçekçi gösterir"],"disadvantages":["Tek oranla özetlenemez"],"suitable":"Borçlu şirketler","caveat":"Sabit/değişken faiz ve para birimini de analiz et.","related":["Interest Coverage","Net Debt/EBITDA"],"source":"Credit analysis","kind":"Metric","rank":40},{"id":41,"category":"Nakit Akışı ve Kâr Kalitesi","name":"Faaliyet Nakit Akımı / Net Kâr","short":"CFO / Net Income","definition":"Kârın ne ölçüde nakde dönüştüğünü ölçer.","formula":"CFO / Net Kâr","interpretation":"Uzun dönemde 1x civarı veya üzeri güçlü kâr kalitesini destekler.","bands":[{"label":"Güçlü","text":"≥1.0x"},{"label":"İzle","text":"0.8–1.0x"},{"label":"Uyarı","text":"<0.8x birkaç yıl."}],"advantages":["Kâr kalitesini basit test eder"],"disadvantages":["Working capital tek yılı bozar"],"suitable":"Kârlı şirketler","caveat":"3 yıllık toplam CFO / toplam net kâr daha sağlamdır.","related":["Accrual Ratio","FCF"],"source":"Cash flow analysis","kind":"Metric","rank":41},{"id":42,"category":"Nakit Akışı ve Kâr Kalitesi","name":"Serbest Nakit Akımı","short":"FCF","definition":"Operasyon nakdinden sermaye harcamaları çıkarıldıktan sonra kalan nakittir.","formula":"FCF ≈ CFO − Capex","interpretation":"Pozitif ve büyüyen FCF finansal esneklik sağlar.","bands":[{"label":"İyi","text":"Pozitif, büyüyen ve net kârla uyumlu."},{"label":"Uyarı","text":"Uzun süre negatif ve dış finansmana bağımlı."}],"advantages":["Değerlemenin temel girdisi"],"disadvantages":["Growth capex FCF’yi düşürebilir"],"suitable":"Finansal olmayan şirketler","caveat":"Bankalarda klasik FCF kullanılmaz.","related":["FCF Margin","FCF Yield"],"source":"Damodaran","kind":"Metric","rank":42},{"id":43,"category":"Nakit Akışı ve Kâr Kalitesi","name":"FCF Marjı","short":"FCF Margin","definition":"Satışların ne kadarının serbest nakde dönüştüğünü ölçer.","formula":"FCF / Hasılat × 100","interpretation":"Yüksek ve stabil FCF marjı güçlü nakit ekonomisi gösterir.","bands":[{"label":"Güçlü","text":"%10+ asset-light işlerde."},{"label":"Çok Güçlü","text":"%20+ yüksek kaliteli asset-light."},{"label":"Uyarı","text":"Kalıcı negatif."}],"advantages":["Nakit dönüşümünü satışa bağlar"],"disadvantages":["Capex döngüsüne duyarlı"],"suitable":"Asset-light ve trend amaçlı sanayi","caveat":"Sermaye yoğunluğu eşikleri değiştirir.","related":["FCF Yield","EBIT Margin"],"source":"Cash flow analysis","kind":"Metric","rank":43},{"id":44,"category":"Nakit Akışı ve Kâr Kalitesi","name":"Accrual Ratio – Tahakkuk Oranı","short":"Accrual Ratio","definition":"Kârın ne kadarının nakit yerine tahakkuktan geldiğini ölçer.","formula":"(Net Kâr − CFO) / Ortalama Toplam Varlıklar","interpretation":"Yüksek pozitif accrual kâr kalitesi için uyarıdır.","bands":[{"label":"İyi","text":"Negatif veya sıfıra yakın."},{"label":"Uyarı","text":"+%5–10 üzeri ve kalıcı."}],"advantages":["Forensic alarm sağlar"],"disadvantages":["Büyüme working-capital ihtiyacı da accrual yaratır"],"suitable":"Tüm şirketler","caveat":"Trend ve iş modeliyle yorumla.","related":["CFO/Net Kâr","Beneish M"],"source":"Forensic accounting","kind":"Metric","rank":44},{"id":45,"category":"Nakit Akışı ve Kâr Kalitesi","name":"Capex / Satışlar","short":"Capex / Sales","definition":"Satışlara göre sermaye yatırım yoğunluğunu ölçer.","formula":"Capex / Revenue × 100","interpretation":"Yüksek capex ancak yüksek ROIC ile değer yaratır.","bands":[{"label":"Yorum","text":"Mutlak iyi/kötü eşik yok; sektör ve growth/maintenance ayrımı gerekir."}],"advantages":["Sermaye yoğunluğunu gösterir"],"disadvantages":["Growth ve maintenance capex ayrımı zor"],"suitable":"Sanayi, enerji, telekom","caveat":"ROIC ve FCF ile birlikte bak.","related":["ROIC","FCF"],"source":"Capital investment","kind":"Metric","rank":45},{"id":46,"category":"Verimlilik ve İşletme Sermayesi","name":"Aktif Devir Hızı","short":"Asset Turnover","definition":"Varlık başına ne kadar satış üretildiğini ölçer.","formula":"Hasılat / Ortalama Toplam Varlıklar","interpretation":"Yüksek oran varlık kullanım verimliliğini gösterir.","bands":[{"label":"Yorum","text":"Sektör ve tarihine göre yüksek/artan olumlu."}],"advantages":["DuPont analizinde faydalı"],"disadvantages":["Sektörler arası kıyas zayıf"],"suitable":"Perakende, sanayi","caveat":"M&A ve revaluation tabanı değiştirir.","related":["ROA","DuPont"],"source":"SEC","kind":"Metric","rank":46},{"id":47,"category":"Verimlilik ve İşletme Sermayesi","name":"Stok Devir Hızı","short":"Inventory Turnover","definition":"Stokların yılda kaç kez satılıp yenilendiğini ölçer.","formula":"COGS / Ortalama Stok","interpretation":"Düşen turnover stok birikimi gösterebilir.","bands":[{"label":"İyi","text":"Sektör medyanına göre yüksek ve stabil."},{"label":"Uyarı","text":"Turnover düşüyor, stok günleri artıyor."}],"advantages":["Stok kalitesini izler"],"disadvantages":["Sezonsallık etkiler"],"suitable":"Perakende, üretim","caveat":"Stok değer düşüklüğü riskini kontrol et.","related":["DIO","Gross Margin"],"source":"SEC","kind":"Metric","rank":47},{"id":48,"category":"Verimlilik ve İşletme Sermayesi","name":"Stokta Kalma Süresi","short":"DIO","definition":"Stokların ortalama kaç günde satıldığını ölçer.","formula":"Ortalama Stok / COGS × 365","interpretation":"Düşmesi genelde working-capital verimliliği sağlar.","bands":[{"label":"Yorum","text":"Mutlak eşik yerine sektör ve trend."}],"advantages":["Gün cinsinden sezgisel"],"disadvantages":["Sezonsallığa duyarlı"],"suitable":"Perakende, üretim","caveat":"Brüt marj düşerken DIO artıyorsa indirim riski.","related":["DSO","CCC"],"source":"Working capital","kind":"Metric","rank":48},{"id":49,"category":"Verimlilik ve İşletme Sermayesi","name":"Alacak Tahsil Süresi","short":"DSO","definition":"Müşteri alacaklarının ortalama tahsil süresidir.","formula":"Ortalama Alacak / Kredili Satış × 365","interpretation":"DSO’nun satıştan hızlı artması tahsilat/agresif gelir tanıma uyarısıdır.","bands":[{"label":"İyi","text":"Stabil veya düşen."},{"label":"Uyarı","text":"Satıştan çok daha hızlı yükselen DSO."}],"advantages":["Gelir kalitesi alarmı"],"disadvantages":["İş modeline göre doğal fark"],"suitable":"B2B şirketler","caveat":"Factoring DSO’yu yapay iyileştirebilir.","related":["CFO/Net Kâr","CCC"],"source":"Working capital","kind":"Metric","rank":49},{"id":50,"category":"Verimlilik ve İşletme Sermayesi","name":"Borç Ödeme Süresi","short":"DPO","definition":"Tedarikçilere borçların ortalama ödeme süresidir.","formula":"Ortalama Ticari Borç / COGS × 365","interpretation":"Yüksek DPO finansman avantajı olabilir; aşırı artış stres gösterebilir.","bands":[{"label":"Yorum","text":"Sektör ve trend ile yorumlanır."}],"advantages":["Ücretsiz finansmanı gösterir"],"disadvantages":["Ödeme gecikmesini kalite sanabilir"],"suitable":"Perakende, üretim","caveat":"Tedarikçi ilişkisini kontrol et.","related":["DIO","CCC"],"source":"Working capital","kind":"Metric","rank":50},{"id":51,"category":"Verimlilik ve İşletme Sermayesi","name":"Nakit Dönüşüm Döngüsü","short":"CCC","definition":"Stoka bağlanan nakdin satış/tahsilat sonrası geri dönüş süresidir.","formula":"CCC = DIO + DSO − DPO","interpretation":"Düşük CCC daha az working capital ihtiyacı demektir.","bands":[{"label":"Güçlü","text":"Sektör medyanından düşük ve iyileşen."},{"label":"Çok Güçlü","text":"Negatif CCC bazı perakende/platformlarda yapısal avantaj."}],"advantages":["Working capital’ı tek ölçüde toplar"],"disadvantages":["Hizmetlerde az anlamlı"],"suitable":"Perakende, üretim, dağıtım","caveat":"Factoring veya zorunlu ödeme gecikmesi etkisini ayır.","related":["DIO","DSO","DPO"],"source":"Working capital","kind":"Metric","rank":51},{"id":52,"category":"Sermaye Tahsisi ve Hissedar Getirisi","name":"Temettü Ödeme Oranı","short":"Payout Ratio","definition":"Net kârın ne kadarının temettü olarak dağıtıldığını gösterir.","formula":"Temettü / Net Kâr × 100","interpretation":"Dengeli payout temettü ve yatırım ihtiyacını birlikte yönetir.","bands":[{"label":"Genel Sağlıklı","text":"%30–60 olgun şirketlerde."},{"label":"Yüksek","text":">%80; FCF coverage kontrol edilmeli."}],"advantages":["Temettü sürdürülebilirliği"],"disadvantages":["REIT gibi yapılarda doğal yüksek"],"suitable":"Olgun şirketler","caveat":"FCF payout da kontrol et.","related":["Dividend Yield","FCF"],"source":"Dividend analysis","kind":"Metric","rank":52},{"id":53,"category":"Sermaye Tahsisi ve Hissedar Getirisi","name":"Hisse Geri Alım Verimi","short":"Buyback Yield","definition":"Net buyback’in piyasa değerine oranıdır.","formula":"Net Buyback / Ortalama Market Cap × 100","interpretation":"Pozitif buyback yield hisse sayısını azaltabilir.","bands":[{"label":"Olumlu","text":"Pozitif ve FCF ile finanse edilen."},{"label":"Uyarı","text":"Borçla pahalı fiyattan veya sadece SBC telafisi."}],"advantages":["Hissedar getirisinin temettü dışı kısmı"],"disadvantages":["Zamanlama kötü olabilir"],"suitable":"Nakit üreten şirketler","caveat":"Net share count gerçekten düşüyor mu kontrol et.","related":["Share Count","FCF"],"source":"Capital allocation","kind":"Metric","rank":53},{"id":54,"category":"Sermaye Tahsisi ve Hissedar Getirisi","name":"Shareholder Yield","short":"Shareholder Yield","definition":"Temettü + net buyback’in toplam hissedar getiri verimidir.","formula":"Dividend Yield + Net Buyback Yield","interpretation":"Olgun şirketlerde sermaye tahsisini özetler.","bands":[{"label":"Yorum","text":"Risk-free rate, growth ve borç değişimiyle kıyaslanır."}],"advantages":["Temettü ve buyback’i birleştirir"],"disadvantages":["Borçla finanse dağıtımı cezalandırmaz"],"suitable":"Olgun şirketler","caveat":"Net debt değişimini ayrıca kontrol et.","related":["Dividend Yield","Buyback Yield"],"source":"Capital allocation","kind":"Metric","rank":54},{"id":55,"category":"Sermaye Tahsisi ve Hissedar Getirisi","name":"Reinvestment Rate","short":"Reinvestment","definition":"NOPAT’ın büyüme için yeniden yatırıma ayrılan kısmıdır.","formula":"(Net Capex + ΔNWC) / NOPAT","interpretation":"Yüksek reinvestment ancak ROIC>WACC ise değer yaratır.","bands":[{"label":"Değer Yaratır","text":"Yüksek reinvestment + ROIC>WACC."},{"label":"Değer Yok Eder","text":"Yüksek reinvestment + ROIC<WACC."}],"advantages":["Growth kalitesini ölçer"],"disadvantages":["Hesaplama ayar gerektirir"],"suitable":"Büyüyen şirketler","caveat":"Büyümenin kendisi değil excess return ile büyüme değerlidir.","related":["ROIC","FCFF"],"source":"Damodaran","kind":"Metric","rank":55},{"id":56,"category":"Sermaye Tahsisi ve Hissedar Getirisi","name":"Sürdürülebilir Büyüme Oranı","short":"SGR","definition":"Mevcut ROE ve retention ile dış özkaynak olmadan sürdürülebilecek teorik büyümedir.","formula":"ROE × (1 − Payout Ratio)","interpretation":"Gerçek growth sürekli SGR üstündeyse dış finansman ihtiyacı doğabilir.","bands":[{"label":"Yorum","text":"Gerçek büyümeyle karşılaştır."}],"advantages":["Growth-finansman ilişkisini gösterir"],"disadvantages":["Sabit ROE/payout varsayımı"],"suitable":"Olgun şirketler","caveat":"Borç kapasitesi ayrıca değerlendirilmelidir.","related":["ROE","Payout"],"source":"Corporate finance","kind":"Metric","rank":56},{"id":57,"category":"Forensic / Finansal Sağlık ve Kırmızı Bayraklar","name":"Altman Z-Score","short":"Altman Z","definition":"Finansal distress/iflas riskini çoklu oranlarla tarayan klasik modeldir.","formula":"Z = 1.2X1 + 1.4X2 + 3.3X3 + 0.6X4 + 1.0X5 (orijinal halka açık imalat modeli)","interpretation":"Düşük skor distress riskinin arttığını gösterir.","bands":[{"label":"Güvenli","text":">2.99"},{"label":"Gri","text":"1.81–2.99"},{"label":"Distress","text":"<1.81"}],"advantages":["Çoklu göstergeleri birleştirir"],"disadvantages":["Her sektör/ülkeye uygun değildir"],"suitable":"Özellikle imalat","caveat":"Finansallar ve yeni ekonomi için alternatif model gerekir.","related":["Interest Coverage","Current Ratio"],"source":"Altman","kind":"Metric","rank":57},{"id":58,"category":"Forensic / Finansal Sağlık ve Kırmızı Bayraklar","name":"Piotroski F-Score","short":"Piotroski F","definition":"Kârlılık, kaldıraç/likidite ve operasyonel verimlilikte 9 ikili testi toplar.","formula":"0–9 skor","interpretation":"Yüksek skor temel finansal momentumun güçlü olduğunu gösterir.","bands":[{"label":"Güçlü","text":"8–9"},{"label":"Orta","text":"3–7"},{"label":"Zayıf","text":"0–2"}],"advantages":["Value hisselerinde kalite filtresi"],"disadvantages":["Tek başına alım sinyali değildir"],"suitable":"Value / düşük P/B","caveat":"Sektör bağlamı gerekli.","related":["P/B","ROA","CFO"],"source":"Piotroski","kind":"Metric","rank":58},{"id":59,"category":"Forensic / Finansal Sağlık ve Kırmızı Bayraklar","name":"Beneish M-Score","short":"Beneish M","definition":"Finansal tablo manipülasyonu olasılığını sekiz değişkenle tarar.","formula":"M = −4.84 + 0.92DSRI + 0.528GMI + 0.404AQI + 0.892SGI + 0.115DEPI − 0.172SGAI + 4.679TATA − 0.327LVGI","interpretation":"Daha yüksek/az negatif skor manipülasyon riskini artırır.","bands":[{"label":"Uyarı","text":"M > −1.78"},{"label":"Daha Düşük Risk","text":"M ≤ −1.78"}],"advantages":["Muhasebe anomalilerini tarar"],"disadvantages":["False positive üretir"],"suitable":"Finansal olmayan şirketler","caveat":"Kesin fraud kanıtı değildir.","related":["Accrual Ratio","DSO"],"source":"Beneish","kind":"Metric","rank":59},{"id":60,"category":"Forensic / Finansal Sağlık ve Kırmızı Bayraklar","name":"Net Kâr – CFO Ayrışması","short":"Earnings-Cash Divergence","definition":"Net kâr ile faaliyet nakit akımının trend farkını izler.","formula":"CFO Growth − Net Income Growth","interpretation":"Kâr büyürken CFO geride kalıyorsa kalite alarmıdır.","bands":[{"label":"İyi","text":"CFO ve net kâr birlikte büyür."},{"label":"Uyarı","text":"2–3 yıl kâr artışı + zayıf/negatif CFO."}],"advantages":["Basit forensic test"],"disadvantages":["Growth working capital geçici ayrışma yaratır"],"suitable":"Tüm şirketler","caveat":"DSO/DIO ile teyit et.","related":["CFO/Net Kâr","Accrual Ratio"],"source":"Forensic analysis","kind":"Metric","rank":60},{"id":61,"category":"Forensic / Finansal Sağlık ve Kırmızı Bayraklar","name":"Hisse Sayısı Değişimi / Dilution","short":"Share Dilution","definition":"Diluted share count’un zaman içindeki artışını ölçer.","formula":"Diluted Shares_t / Diluted Shares_t−1 − 1","interpretation":"Sürekli dilution yatırımcının ekonomik payını azaltır.","bands":[{"label":"Olumlu","text":"Hisse sayısı stabil/düşüyor."},{"label":"Uyarı","text":"Yıllık %3–5+ kalıcı dilution."}],"advantages":["SBC etkisini görünür kılar"],"disadvantages":["M&A karşılığı hisse ihracı değer yaratabilir"],"suitable":"Teknoloji, growth","caveat":"EPS growth’u share count ile teyit et.","related":["EPS Growth","Buyback Yield"],"source":"Financial statements","kind":"Metric","rank":61},{"id":62,"category":"Değerleme Modelleri","name":"DCF – İskonto Edilmiş Nakit Akımları","short":"DCF","definition":"Gelecekteki serbest nakit akımlarını uygun iskonto oranıyla bugüne getirerek içsel değeri hesaplar.","formula":"EV = Σ FCFF_t/(1+WACC)^t + TV/(1+WACC)^n; Equity = EV − Net Debt + Non-operating Assets","interpretation":"Büyüme, marj, reinvestment, WACC ve terminal varsayımlarının tamamı tutarlı olmalıdır.","bands":[{"label":"İyi Kullanım","text":"Bear/base/bull + sensitivity."},{"label":"Uyarı","text":"Aşırı terminal growth, düşük WACC, peak margin."}],"advantages":["İçsel değer çerçevesi","Ekonomik sürücüleri zorunlu kılar"],"disadvantages":["Varsayımlara çok hassas"],"suitable":"Öngörülebilir nakit akımlı şirketler","caveat":"DCF tek hedef değil değer aralığıdır.","related":["FCFF","WACC","Terminal Value"],"source":"NYU Damodaran","kind":"Valuation Model","rank":62},{"id":63,"category":"Değerleme Modelleri","name":"FCFF DCF","short":"FCFF","definition":"Firmaya ait serbest nakit akımlarını WACC ile iskonto eder.","formula":"FCFF = EBIT(1−T)+D&A−Capex−ΔNWC; EV = PV(FCFF)","interpretation":"Önce enterprise value, sonra net borç çıkarılarak equity value bulunur.","bands":[{"label":"Uygun","text":"Borç yapısı değişen finansal olmayan şirketler."}],"advantages":["Sermaye yapısından daha bağımsız"],"disadvantages":["WACC/invested capital ayarı gerekir"],"suitable":"Sanayi, teknoloji, tüketici","caveat":"Bankalarda uygun değildir.","related":["DCF","WACC"],"source":"NYU Damodaran","kind":"Valuation Model","rank":63},{"id":64,"category":"Değerleme Modelleri","name":"FCFE DCF","short":"FCFE","definition":"Özkaynak yatırımcısına kalan nakit akımlarını cost of equity ile iskonto eder.","formula":"FCFE = Net Kâr + D&A − Capex − ΔNWC + Net Borrowing","interpretation":"Doğrudan equity value verir.","bands":[{"label":"Uygun","text":"Borç politikası istikrarlı şirketler."}],"advantages":["Doğrudan hisse değeri"],"disadvantages":["Net borçlanma varsayımına hassas"],"suitable":"Olgun finansal olmayan şirketler","caveat":"Leverage hızla değişiyorsa FCFF daha sağlam.","related":["Cost of Equity","CAPM"],"source":"NYU Damodaran","kind":"Valuation Model","rank":64},{"id":65,"category":"Değerleme Modelleri","name":"DDM – Temettü İskonto Modeli","short":"DDM","definition":"Hisse değerini gelecekte beklenen temettülerin bugünkü değeri olarak hesaplar.","formula":"Value = Σ Dividend_t/(1+Ke)^t","interpretation":"Temettü politikası earning power’ı iyi temsil eden şirketlerde etkilidir.","bands":[{"label":"Uygun","text":"Olgun, düzenli ve öngörülebilir temettülü şirketler."}],"advantages":["Basit","Bankalarda kullanışlı"],"disadvantages":["Temettü ödemeyende kullanılamaz"],"suitable":"Bankalar, utilities, holdingler","caveat":"Payout politikası değişiyorsa FCFE/residual income düşün.","related":["Gordon DDM","Payout"],"source":"NYU Damodaran","kind":"Valuation Model","rank":65},{"id":66,"category":"Değerleme Modelleri","name":"Gordon Growth DDM","short":"Gordon DDM","definition":"Temettünün sonsuza kadar sabit büyüdüğü stabil dönem modelidir.","formula":"P0 = D1 / (Ke − g)","interpretation":"Ke-g farkı küçüldükçe değer çok hassas olur.","bands":[{"label":"Kural","text":"g < Ke olmalı; uzun dönem g sürdürülebilir nominal ekonomi büyümesini aşmamalı."}],"advantages":["Basit terminal model"],"disadvantages":["g ve Ke’ye aşırı hassas"],"suitable":"Olgun stabil şirketler","caveat":"Yüksek-growth şirkete tek aşama uygulama.","related":["DDM","Cost of Equity"],"source":"NYU Damodaran","kind":"Valuation Model","rank":66},{"id":67,"category":"Değerleme Modelleri","name":"İki Aşamalı DDM","short":"Two-Stage DDM","definition":"Yüksek büyüme dönemi + stabil terminal dönemi kullanır.","formula":"Yüksek büyüme temettü PV + Gordon terminal PV","interpretation":"Büyümesi olgunlaşacak temettü şirketleri için kullanışlıdır.","bands":[{"label":"Uygun","text":"Büyümesi yavaşlayacak banka/holding/olgunlaşan şirket."}],"advantages":["Tek aşamadan gerçekçi"],"disadvantages":["Geçiş varsayımı gerekir"],"suitable":"Bankalar, dividend growth","caveat":"ROE-retention-growth tutarlılığına bak.","related":["ROE","Retention"],"source":"NYU Damodaran","kind":"Valuation Model","rank":67},{"id":68,"category":"Değerleme Modelleri","name":"Üç Aşamalı DDM","short":"Three-Stage DDM","definition":"Yüksek büyüme, geçiş ve stabil büyüme olmak üzere üç aşama kullanır.","formula":"Aşama 1 PV + geçiş temettü PV + terminal Gordon PV","interpretation":"Uzun geçiş dönemi olan şirketlerde daha esnektir.","bands":[{"label":"Uygun","text":"Uzun olgunlaşma dönemi olan kaliteli growth."}],"advantages":["Daha gerçekçi geçiş"],"disadvantages":["Çok fazla varsayım"],"suitable":"Büyük growth şirketleri","caveat":"False precision riski.","related":["Two-Stage DDM","Cost of Equity"],"source":"Valuation theory","kind":"Valuation Model","rank":68},{"id":69,"category":"Değerleme Modelleri","name":"Göreli Değerleme / Çarpan Analizi","short":"Relative Valuation","definition":"Benzer şirketlerin çarpanlarıyla hedef şirketi karşılaştırır.","formula":"Implied Value = Peer Multiple × Target Fundamental","interpretation":"Doğru peer ve growth/margin/ROIC farklarının normalizasyonu kritiktir.","bands":[{"label":"İyi","text":"Gerçek peers + normalized fundamentals."},{"label":"Uyarı","text":"Sadece sektör ortalamasını kör kullanmak."}],"advantages":["Hızlı ve piyasa gerçekliğine yakın"],"disadvantages":["Piyasanın tamamı pahalı/ucuz olabilir"],"suitable":"Hemen tüm şirketler","caveat":"Çarpan farkını büyüme, marj ve riskle açıklamalısın.","related":["P/E","EV/EBITDA","P/B"],"source":"NYU Damodaran","kind":"Valuation Model","rank":69},{"id":70,"category":"Değerleme Modelleri","name":"NAV – Net Aktif Değeri","short":"NAV","definition":"Varlıkların gerçeğe uygun değerinden borçların çıkarılmasıyla özkaynak değeri tahmin edilir.","formula":"NAV = Fair Value of Assets − Liabilities","interpretation":"Varlık değerinin operasyonel kârdan önemli olduğu yapılarda kullanılır.","bands":[{"label":"Uygun","text":"Holding, GYO/REIT, maden, yatırım şirketi."}],"advantages":["Asset-heavy işlerde güçlü"],"disadvantages":["İştirak/illikit varlık değerlemesi zor"],"suitable":"Holding, gayrimenkul, maden","caveat":"Holding discount ve vergi/likidite maliyeti düşün.","related":["SOTP","P/NAV"],"source":"Asset valuation","kind":"Valuation Model","rank":70},{"id":71,"category":"Değerleme Modelleri","name":"Likidasyon Değeri","short":"Liquidation Value","definition":"Şirket kapanırsa varlık satış gelirlerinden tüm yükümlülük ve wind-down giderleri çıkarılır.","formula":"Recoverable Asset Proceeds − Liabilities − Wind-down Costs","interpretation":"Downside/floor senaryosu sağlar.","bands":[{"label":"Uygun","text":"Distressed / iflas riski / kapanma."}],"advantages":["Downside floor"],"disadvantages":["Fire-sale iskonto tahmini zor"],"suitable":"Distressed şirketler","caveat":"Normal faaliyet değeriyle karıştırma.","related":["NAV","Altman Z"],"source":"Distressed valuation","kind":"Valuation Model","rank":71},{"id":72,"category":"Değerleme Modelleri","name":"EVA – Ekonomik Katma Değer","short":"EVA","definition":"Yatırılan sermayenin maliyetini aştıktan sonra kalan ekonomik kârdır.","formula":"EVA = NOPAT − WACC×Invested Capital","interpretation":"Pozitif EVA değer yaratımıdır.","bands":[{"label":"İyi","text":"Pozitif ve büyüyen."},{"label":"Kötü","text":"Kalıcı negatif."}],"advantages":["Sermaye maliyetini açıkça içerir"],"disadvantages":["Muhasebe ayarları gerekir"],"suitable":"Sermaye yoğun şirketler","caveat":"NOPAT/invested capital tanımı tutarlı olmalı.","related":["ROIC","WACC"],"source":"Corporate finance","kind":"Valuation Model","rank":72},{"id":73,"category":"Değerleme Modelleri","name":"Residual Income Model","short":"Residual Income","definition":"Özkaynak maliyetini aşan kârların PV’sini book equity’ye ekler.","formula":"RI_t = Net Income_t − Ke×Beginning Book Equity; Value = Book Equity_0 + PV(RI)","interpretation":"Book value anlamlı ve temettü/FCF zor ise güçlü alternatiftir.","bands":[{"label":"Uygun","text":"Bankalar, finansallar, book value anlamlı şirketler."}],"advantages":["Bankalarda güçlü"],"disadvantages":["Muhasebe özkaynağı kalitesine bağlı"],"suitable":"Bankalar, sigorta","caveat":"Clean-surplus ilişkisi bozulursa ayar gerekir.","related":["P/B","ROE"],"source":"Valuation theory","kind":"Valuation Model","rank":73},{"id":74,"category":"Değerleme Modelleri","name":"SOTP – Parçaların Toplamı","short":"SOTP","definition":"Farklı iş kollarını ayrı değerleyip holding borç/diğer kalemleri çıkarır.","formula":"Equity = Σ Segment Values − Net Debt ± Other Assets/Liabilities","interpretation":"Konglomeralarda her segmente uygun model/çarpan kullanılır.","bands":[{"label":"Uygun","text":"Holdingler, çok segmentli şirketler."}],"advantages":["Karmaşık yapıyı çözer"],"disadvantages":["Segment finansalları yetersiz olabilir"],"suitable":"Holdingler, konglomeralar","caveat":"Merkez gideri, vergi ve holding discount’u unutma.","related":["NAV","DCF"],"source":"Valuation practice","kind":"Valuation Model","rank":74},{"id":75,"category":"Değerleme Modelleri","name":"Asset-Based Valuation","short":"Asset-Based","definition":"Tüm varlıkları fair value’ya getirip yükümlülükleri çıkarır.","formula":"Adjusted Fair Value of Assets − Adjusted Liabilities","interpretation":"Kâr gücünden çok varlık değeri önemliyse kullanılır.","bands":[{"label":"Uygun","text":"Gayrimenkul, maden, shipping, yatırım holdingi."}],"advantages":["Somut varlık tabanı"],"disadvantages":["Marka/network effect eksik değerlenebilir"],"suitable":"Asset-heavy şirketler","caveat":"Going concern değeriyle liquidation değeri aynı değildir.","related":["NAV","Liquidation Value"],"source":"Asset valuation","kind":"Valuation Model","rank":75},{"id":76,"category":"Değerleme Modelleri","name":"Reverse DCF","short":"Reverse DCF","definition":"Mevcut piyasa fiyatını haklı çıkarmak için gereken growth/margin varsayımlarını geriye çözer.","formula":"Market Price = DCF output olacak şekilde growth/margin solve edilir.","interpretation":"Piyasanın ne fiyatladığını gösterir.","bands":[{"label":"İyi Kullanım","text":"Implied growth/margin’i şirket kapasitesiyle karşılaştır."}],"advantages":["Forecast anchoring’i azaltır"],"disadvantages":["Yine DCF varsayımlarına bağlı"],"suitable":"Yüksek çarpanlı growth şirketleri","caveat":"Tek implied parametre diğer varsayımlara bağlıdır.","related":["DCF","ROIC"],"source":"Damodaran-style","kind":"Valuation Model","rank":76},{"id":77,"category":"Değerleme Modelleri","name":"WACC – Ağırlıklı Ortalama Sermaye Maliyeti","short":"WACC","definition":"Borç ve özkaynak finansmanının vergi sonrası ağırlıklı fırsat maliyetidir.","formula":"E/(D+E)×Ke + D/(D+E)×Kd×(1−T)","interpretation":"FCFF DCF iskonto oranıdır; ROIC ile karşılaştırılır.","bands":[{"label":"Kural","text":"ROIC > WACC değer yaratır."}],"advantages":["Sermaye maliyetini toplar"],"disadvantages":["Beta/ERP/borç maliyetine hassas"],"suitable":"DCF, EVA","caveat":"Piyasa değer ağırlıkları kullan.","related":["ROIC","CAPM"],"source":"NYU Damodaran","kind":"Valuation Input","rank":77},{"id":78,"category":"Değerleme Modelleri","name":"CAPM – Özsermaye Maliyeti","short":"CAPM","definition":"Sistematik riske göre yatırımcının beklediği özsermaye getirisini tahmin eder.","formula":"Ke = Rf + β×ERP (+ Country Risk Premium)","interpretation":"Beta ve risk primi arttıkça required return artar.","bands":[{"label":"Kural","text":"Equity cash flow’ları Ke ile iskonto edilir."}],"advantages":["Standart ve yaygın"],"disadvantages":["Tek faktörlü basitleştirme"],"suitable":"Equity valuation","caveat":"Para birimi, Rf ve ERP tutarlı olmalı.","related":["Beta","WACC"],"source":"CAPM / Damodaran","kind":"Valuation Input","rank":78},{"id":79,"category":"Değerleme Modelleri","name":"Terminal Value – Gordon","short":"Terminal Value (Gordon)","definition":"Açık tahmin dönemi sonrası sonsuz cash flow değeridir.","formula":"TV = FCF_(n+1) / (WACC − g)","interpretation":"DCF’nin büyük kısmını oluşturabilir.","bands":[{"label":"Disiplin","text":"g < WACC; g uzun vadede ekonominin sürdürülebilir nominal büyümesini aşmamalı."}],"advantages":["Ekonomik olarak tutarlı"],"disadvantages":["WACC-g farkına çok hassas"],"suitable":"DCF","caveat":"Terminal marj/ROIC olgun seviyeye normalize edilmeli.","related":["DCF","WACC"],"source":"NYU Damodaran","kind":"Valuation Input","rank":79},{"id":80,"category":"Değerleme Modelleri","name":"Terminal Value – Exit Multiple","short":"Terminal Value (Multiple)","definition":"Terminal yıldaki fundamentale seçilen piyasa çarpanı uygulanır.","formula":"Terminal Metric × Exit Multiple","interpretation":"DCF içine relative valuation varsayımı taşır.","bands":[{"label":"İyi","text":"Normalize terminal EBITDA/EBIT + cycle-normal multiple."}],"advantages":["Piyasa pratiğine yakın"],"disadvantages":["DCF’yi market multiple’a bağımlı yapar"],"suitable":"M&A, PE","caveat":"Giriş multiple’ını otomatik exit multiple yapma.","related":["EV/EBITDA","Gordon TV"],"source":"Valuation practice","kind":"Valuation Input","rank":80},{"id":81,"category":"Değerleme Modelleri","name":"Hassasiyet Analizi","short":"Sensitivity Analysis","definition":"Değerin WACC, g, marj veya growth değişimine hassasiyetini gösterir.","formula":"Örn. WACC × g valuation matrix","interpretation":"Tek target yerine değer aralığı verir.","bands":[{"label":"İyi","text":"Base etrafında gerçekçi bear/base/bull aralıkları."}],"advantages":["False precision’i azaltır"],"disadvantages":["Kötü modeli iyi yapmaz"],"suitable":"Tüm DCF","caveat":"Marj ve ROIC sensitivity de test et.","related":["DCF","Reverse DCF"],"source":"Valuation practice","kind":"Valuation Input","rank":81},{"id":82,"category":"Nitel Temel Analiz ve İş Modeli","name":"Economic Moat – Rekabet Avantajı","short":"Economic Moat","definition":"Maliyet, marka, network effect, switching cost, ölçek veya regülasyon kaynaklı kalıcı rekabet avantajıdır.","formula":"Formül yok; ROIC, marj ve pazar payı dayanıklılığıyla test edilir.","interpretation":"Kalıcı moat ROIC’in uzun süre WACC üzerinde kalmasını destekler.","bands":[{"label":"Güçlü","text":"Uzun süre yüksek ROIC + stabil marj + pazar payı."},{"label":"Zayıf","text":"Marj erozyonu ve fiyat rekabeti."}],"advantages":["Uzun vadeli değer sürücüsü"],"disadvantages":["Subjektif değerlendirme"],"suitable":"Tüm şirketler","caveat":"Hikâye değil ölçülebilir ROIC/marj kanıtı ara.","related":["ROIC","Gross Margin"],"source":"Fundamental analysis","kind":"Qualitative","rank":82},{"id":83,"category":"Nitel Temel Analiz ve İş Modeli","name":"Fiyatlama Gücü","short":"Pricing Power","definition":"Müşteri kaybetmeden fiyat artırabilme kapasitesidir.","formula":"Fiyat artışı + hacim etkisi + brüt marj birlikte incelenir.","interpretation":"Fiyat artışı + stabil hacim/marj güçlü moat sinyalidir.","bands":[{"label":"Güçlü","text":"Fiyat artışı + stabil hacim + stabil/artan gross margin."}],"advantages":["Enflasyon dayanıklılığı"],"disadvantages":["Mix etkisi sinyali karıştırabilir"],"suitable":"Markalı tüketici, yazılım","caveat":"Bir yıllık inflation pass-through’u kalıcı moat sanma.","related":["Gross Margin","Volume Growth"],"source":"Fundamental analysis","kind":"Qualitative","rank":83},{"id":84,"category":"Nitel Temel Analiz ve İş Modeli","name":"Yönetim Kalitesi ve Sermaye Tahsisi","short":"Management Quality","definition":"Yönetimin organik yatırım, M&A, borç, temettü ve buyback kararlarının kalitesidir.","formula":"ROIC trendi + M&A sonrası getiri + share count + leverage + guidance credibility","interpretation":"İyi yönetim uzun vadede hisse başına değer yaratır.","bands":[{"label":"Güçlü","text":"ROIC disiplini, makul leverage, değer artırıcı M&A/buyback."},{"label":"Uyarı","text":"Empire building, pahalı M&A, sürekli dilution."}],"advantages":["Compounder kalitesini belirler"],"disadvantages":["Subjektif ve gecikmeli"],"suitable":"Tüm şirketler","caveat":"Söylemden çok geçmiş karar sonuçlarına bak.","related":["ROIC","Buyback Yield"],"source":"Fundamental analysis","kind":"Qualitative","rank":84},{"id":85,"category":"Nitel Temel Analiz ve İş Modeli","name":"Müşteri Konsantrasyonu","short":"Customer Concentration","definition":"Satışların az sayıda müşteriye bağımlılığını ölçer.","formula":"Top 1 / Top 5 müşteri satış payı","interpretation":"Yüksek konsantrasyon pazarlık gücü ve gelir riskini artırır.","bands":[{"label":"Uyarı","text":"Tek müşteri %20–30+ satış payı çoğu işte maddi risk."}],"advantages":["Gelir riskini gösterir"],"disadvantages":["Büyük stratejik kontrat kaliteli olabilir"],"suitable":"B2B, savunma, tedarikçi","caveat":"Sözleşme süresi ve switching cost’u incele.","related":["Receivables","Backlog"],"source":"Company disclosures","kind":"Qualitative","rank":85},{"id":86,"category":"Nitel Temel Analiz ve İş Modeli","name":"Döngüsellik","short":"Cyclicality","definition":"Satış/kârların ekonomi, emtia, faiz veya yatırım döngüsüne duyarlılığıdır.","formula":"Peak-to-trough revenue/margin ve normalize earnings analizi","interpretation":"Döngüsel şirket peak kârda düşük P/E ile yanıltıcı ucuz görünebilir.","bands":[{"label":"Disiplin","text":"Mid-cycle earnings ve normalize marj ile değerle."}],"advantages":["Value trap’i azaltır"],"disadvantages":["Cycle timing zordur"],"suitable":"Emtia, otomotiv, semis, bankalar","caveat":"Peak margin × normal multiple hatasına dikkat.","related":["Normalized Earnings","EV/EBITDA"],"source":"Fundamental analysis","kind":"Qualitative","rank":86},{"id":87,"category":"Sektör Özel Metrikler","name":"Bankalarda Net Faiz Marjı","short":"NIM","definition":"Net faiz gelirinin ortalama faiz getirili varlıklara oranıdır.","formula":"Net Faiz Geliri / Ortalama Faiz Getirili Varlıklar","interpretation":"Bankanın pricing/funding avantajını gösterir.","bands":[{"label":"Genel","text":"%2–4 birçok sistemde yaygın; ülke/faiz rejimine bağlı."}],"advantages":["Bank çekirdek kârlılığı"],"disadvantages":["Yield curve etkiler"],"suitable":"Bankalar","caveat":"NPL ve funding kalitesiyle birlikte bak.","related":["ROE","NPL","Cost/Income"],"source":"Bank analysis","kind":"Sector Metric","rank":87},{"id":88,"category":"Sektör Özel Metrikler","name":"Bankalarda Takipteki Kredi Oranı","short":"NPL","definition":"Sorunlu kredilerin toplam krediye oranıdır.","formula":"NPL / Gross Loans × 100","interpretation":"Hızlı artış kredi döngüsü bozulmasını gösterir.","bands":[{"label":"Düşük","text":"<2%"},{"label":"İzle","text":"2–5%"},{"label":"Yüksek","text":">5%; ülkeye göre."}],"advantages":["Kredi kalitesini ölçer"],"disadvantages":["Yapılandırma/charge-off politikası etkiler"],"suitable":"Bankalar","caveat":"Coverage ve Stage 2 ile birlikte bak.","related":["Coverage","CET1"],"source":"Bank analysis","kind":"Sector Metric","rank":88},{"id":89,"category":"Sektör Özel Metrikler","name":"Bankalarda Karşılık Kapsama Oranı","short":"NPL Coverage","definition":"NPL için ayrılan karşılıkların NPL’e oranıdır.","formula":"Loan Loss Reserves / NPL × 100","interpretation":"Yüksek coverage zarar tamponunu artırır.","bands":[{"label":"Güçlü","text":"100%+ sık kullanılan başlangıç; collateral ve ülkeye bağlı."}],"advantages":["Kredi tamponunu gösterir"],"disadvantages":["Teminat politikası fark yaratır"],"suitable":"Bankalar","caveat":"NPL tanımını kontrol et.","related":["NPL","CET1"],"source":"Bank analysis","kind":"Sector Metric","rank":89},{"id":90,"category":"Sektör Özel Metrikler","name":"Bankalarda CET1 Oranı","short":"CET1","definition":"En yüksek kaliteli çekirdek sermayenin RWA’ya oranıdır.","formula":"CET1 Capital / RWA × 100","interpretation":"Regülasyon minimumu üzerindeki buffer dayanıklılığı gösterir.","bands":[{"label":"Kural","text":"Evrensel iyi eşik yok; yasal minimum + management buffer + stress test."}],"advantages":["Sermaye dayanıklılığı"],"disadvantages":["Risk weights modele bağlı"],"suitable":"Bankalar","caveat":"Ülke ve banka özel regülasyon kullan.","related":["NPL","ROE"],"source":"Basel / Bank regulation","kind":"Sector Metric","rank":90},{"id":91,"category":"Sektör Özel Metrikler","name":"Bankalarda Maliyet / Gelir","short":"Cost / Income","definition":"Faaliyet giderlerinin faaliyet gelirine oranıdır.","formula":"Operating Expenses / Operating Income × 100","interpretation":"Daha düşük daha verimli banka operasyonu demektir.","bands":[{"label":"Çok Verimli","text":"<50%"},{"label":"Makul","text":"50–60%"},{"label":"Yüksek Maliyet","text":">60%."}],"advantages":["Kolay kıyas"],"disadvantages":["Growth yatırımı geçici yükseltebilir"],"suitable":"Bankalar","caveat":"Gelir cycle’ı oranı oynatır.","related":["NIM","ROE"],"source":"Bank analysis","kind":"Sector Metric","rank":91},{"id":92,"category":"Sektör Özel Metrikler","name":"Bankalarda Kredi / Mevduat","short":"Loan / Deposit","definition":"Kredilerin müşteri mevduatlarıyla ne ölçüde fonlandığını gösterir.","formula":"Gross Loans / Customer Deposits × 100","interpretation":"Aşırı yüksek oran wholesale funding bağımlılığını artırabilir.","bands":[{"label":"Dengeli","text":"%70–90 birçok bankada."},{"label":"Dikkat","text":">100%."}],"advantages":["Funding yapısını gösterir"],"disadvantages":["Sistem likiditesine bağlı"],"suitable":"Bankalar","caveat":"LCR/NSFR ve deposit beta ile birlikte bak.","related":["NIM","Liquidity"],"source":"Bank analysis","kind":"Sector Metric","rank":92},{"id":93,"category":"Sektör Özel Metrikler","name":"Sigortada Combined Ratio","short":"Combined Ratio","definition":"Hasar + giderlerin earned premium’a oranıdır.","formula":"(Claims + Expenses) / Earned Premium × 100","interpretation":"100 altı underwriting kârı, üstü zarar.","bands":[{"label":"Çok Güçlü","text":"<95%"},{"label":"Kârlı","text":"95–100%"},{"label":"Zarar","text":">100%"}],"advantages":["Underwriting kalitesinin ana metriği"],"disadvantages":["Yatırım gelirini içermez"],"suitable":"P&C sigorta","caveat":"Reserve release etkisini kontrol et.","related":["Loss Ratio","ROE"],"source":"Insurance analysis","kind":"Sector Metric","rank":93},{"id":94,"category":"Sektör Özel Metrikler","name":"REIT/GYO FFO","short":"FFO","definition":"Net kâra gayrimenkul amortismanını geri ekleyip varlık satış kazançlarını çıkarır.","formula":"Net Income + Real Estate D&A − Property Sale Gains","interpretation":"REIT/GYO operasyonel earnings için EPS’den daha uygundur.","bands":[{"label":"Yorum","text":"FFO/share growth, P/FFO ve payout birlikte."}],"advantages":["Amortisman distorsiyonunu azaltır"],"disadvantages":["Maintenance capex’i görmez"],"suitable":"REIT/GYO","caveat":"AFFO ile teyit et.","related":["AFFO","NAV"],"source":"REIT analysis","kind":"Sector Metric","rank":94},{"id":95,"category":"Sektör Özel Metrikler","name":"REIT/GYO AFFO","short":"AFFO","definition":"FFO’dan maintenance capex ve bazı non-cash ayarları çıkarır.","formula":"FFO − Maintenance Capex ± Adjustments","interpretation":"Dağıtılabilir nakde yaklaşır.","bands":[{"label":"Yorum","text":"AFFO payout <100%; çoğu REIT’te %70–90 yaygın."}],"advantages":["Nakit kapasitesine yakın"],"disadvantages":["Şirket tanımları farklı"],"suitable":"REIT/GYO","caveat":"Non-GAAP tanımı kontrol et.","related":["FFO","Dividend Payout"],"source":"REIT analysis","kind":"Sector Metric","rank":95},{"id":96,"category":"Sektör Özel Metrikler","name":"SaaS Rule of 40","short":"Rule of 40","definition":"Gelir büyümesi ile kârlılık marjını toplar.","formula":"Revenue Growth % + FCF Margin % (veya EBITDA Margin)","interpretation":"Growth-kârlılık dengesini tek ölçüde gösterir.","bands":[{"label":"Güçlü","text":"≥40"},{"label":"Çok Güçlü","text":"≥50–60"},{"label":"Zayıf","text":"<30."}],"advantages":["Growth-profitability tradeoff"],"disadvantages":["Marj tanımı değişebilir"],"suitable":"SaaS","caveat":"SBC ve FCF tanımını kontrol et.","related":["EV/Sales","NRR"],"source":"SaaS analysis","kind":"Sector Metric","rank":96},{"id":97,"category":"Sektör Özel Metrikler","name":"Net Revenue Retention","short":"NRR","definition":"Mevcut müşterilerin churn, downgrade ve expansion sonrası gelir retention’ıdır.","formula":"(Starting Revenue − Churn − Contraction + Expansion) / Starting Revenue","interpretation":"100% üzeri mevcut müşteri cohort’u net büyüyor demektir.","bands":[{"label":"Güçlü","text":">110%"},{"label":"Çok Güçlü","text":">120%"},{"label":"Uyarı","text":"<100%"}],"advantages":["Moat ve upsell gücü"],"disadvantages":["Şirket tanımları değişebilir"],"suitable":"SaaS/abonelik","caveat":"Gross retention ve concentration ile bak.","related":["Rule of 40","LTV/CAC"],"source":"SaaS analysis","kind":"Sector Metric","rank":97},{"id":98,"category":"Sektör Özel Metrikler","name":"LTV / CAC","short":"LTV/CAC","definition":"Müşteri yaşam boyu katkı değerini edinme maliyetine oranlar.","formula":"LTV / CAC","interpretation":"Growth unit economics verimliliğini ölçer.","bands":[{"label":"Sağlıklı Başlangıç","text":"~3x+"},{"label":"Zayıf","text":"<1–2x"}],"advantages":["Unit economics’i ölçer"],"disadvantages":["LTV tahminine hassas"],"suitable":"SaaS, fintech","caveat":"CAC payback ve gross margin ile birlikte bak.","related":["NRR","Gross Margin"],"source":"Unit economics","kind":"Sector Metric","rank":98},{"id":99,"category":"Risk ve Performans Metrikleri","name":"Sharpe Oranı","short":"Sharpe Ratio","definition":"Portföyün risksiz faiz üzerindeki excess return’ünü toplam volatilite başına ölçer.","formula":"(R_p − R_f) / σ_p; frekans ve annualization tutarlı olmalı.","interpretation":"Daha yüksek Sharpe risk başına daha yüksek excess return demektir.","bands":[{"label":"Negatif","text":"<0"},{"label":"Zayıf","text":"0–0.5"},{"label":"Makul","text":"0.5–1"},{"label":"İyi","text":"1–2"},{"label":"Çok Güçlü","text":">2; uzun örneklem şart."}],"advantages":["Standart risk-adjusted kıyas"],"disadvantages":["Upside vol’u da risk sayar","Tail risk’i eksik yakalar"],"suitable":"Fonlar ve portföyler","caveat":"Kısa örneklemden yüksek Sharpe güvenilir değildir.","related":["Sortino","Calmar","MaxDD"],"source":"CFA Institute","kind":"Performance Metric","rank":99},{"id":100,"category":"Risk ve Performans Metrikleri","name":"Sortino Oranı","short":"Sortino Ratio","definition":"Fazla getiriyi yalnız downside deviation’a böler.","formula":"(R_p − MAR veya R_f) / Downside Deviation","interpretation":"Upside volatiliteyi cezalandırmadığı için Sharpe’ı tamamlar.","bands":[{"label":"Negatif","text":"<0"},{"label":"Makul","text":"~1"},{"label":"İyi","text":"1–2"},{"label":"Güçlü","text":"2–3"},{"label":"Çok Güçlü","text":">3."}],"advantages":["Downside risk’e odaklanır"],"disadvantages":["MAR seçimine ve az negatif gözleme hassas"],"suitable":"Fonlar ve asimetrik stratejiler","caveat":"Sharpe ile aynı dönem/frekans kullan.","related":["Sharpe","Downside Deviation"],"source":"CFA Institute","kind":"Performance Metric","rank":100},{"id":101,"category":"Risk ve Performans Metrikleri","name":"Treynor Oranı","short":"Treynor Ratio","definition":"Excess return’ü portföy betasına böler.","formula":"(R_p − R_f) / β_p","interpretation":"İyi çeşitlendirilmiş portföylerde sistematik risk başına getiriyi ölçer.","bands":[{"label":"Yorum","text":"Daha yüksek daha iyi; evrensel eşik yok."}],"advantages":["Beta riskine odaklanır"],"disadvantages":["Beta düşük/negatifse sorunlu"],"suitable":"Long-only portföyler","caveat":"Toplam risk önemliyse Sharpe daha uygun.","related":["Beta","Jensen Alpha"],"source":"CFA Institute","kind":"Performance Metric","rank":101},{"id":102,"category":"Risk ve Performans Metrikleri","name":"Information Ratio","short":"Information Ratio","definition":"Aktif getiriyi tracking error’a böler.","formula":"Mean(R_p − R_b) / StdDev(R_p − R_b)","interpretation":"Benchmarka göre aktif yönetim tutarlılığını ölçer.","bands":[{"label":"Zayıf","text":"<0.25"},{"label":"Makul","text":"0.25–0.5"},{"label":"Güçlü","text":"0.5–1"},{"label":"Çok Güçlü","text":">1"}],"advantages":["Aktif yönetim kalitesini ölçer"],"disadvantages":["Benchmark seçimine bağımlı"],"suitable":"Benchmarklı fonlar","caveat":"Aynı benchmark/dönem kullan.","related":["Tracking Error","Alpha"],"source":"CFA Institute","kind":"Performance Metric","rank":102},{"id":103,"category":"Risk ve Performans Metrikleri","name":"Jensen Alpha","short":"Jensen Alpha","definition":"CAPM’in açıklayamadığı risk ayarlı excess return’dür.","formula":"α = R_p − [R_f + β(R_m − R_f)]","interpretation":"Pozitif alpha market beta ile açıklanamayan outperformance’dır.","bands":[{"label":"İyi","text":"Pozitif ve ekonomik/istatistiksel anlamlı."},{"label":"Zayıf","text":"Negatif."}],"advantages":["Beta etkisini ayırır"],"disadvantages":["CAPM ve benchmarka bağlı"],"suitable":"Fonlar","caveat":"Alpha’nın sürekliliğine bak.","related":["Beta","Treynor"],"source":"CFA Institute / CAPM","kind":"Performance Metric","rank":103},{"id":104,"category":"Risk ve Performans Metrikleri","name":"Beta","short":"Beta","definition":"Portföyün benchmark hareketlerine duyarlılığıdır.","formula":"Cov(R_p,R_m) / Var(R_m)","interpretation":"1 piyasa hassasiyeti; <1 daha düşük, >1 daha yüksek sistematik risk.","bands":[{"label":"Düşük","text":"<0.7"},{"label":"Piyasaya Yakın","text":"0.8–1.2"},{"label":"Yüksek","text":">1.3"}],"advantages":["Sistematik risk ölçüsü"],"disadvantages":["Lookback ve rejime göre değişir"],"suitable":"Hisseler/portföyler","caveat":"Beta iyi/kötü değil mandate’e göre risk karakteridir.","related":["Alpha","Correlation"],"source":"CAPM","kind":"Performance Metric","rank":104},{"id":105,"category":"Risk ve Performans Metrikleri","name":"Yıllıklandırılmış Volatilite","short":"Annualized Volatility","definition":"Dönemsel getirilerin standart sapmasını yıllık ölçeğe getirir.","formula":"σ_ann = σ_period × √(periods/year)","interpretation":"Yüksek vol daha büyük fiyat dalgalanmasıdır.","bands":[{"label":"Yorum","text":"Evrensel iyi/kötü yok; benchmark/risk bütçesiyle kıyas."}],"advantages":["Standart risk ölçüsü"],"disadvantages":["Tail risk ve drawdown süresini görmez"],"suitable":"Portföyler","caveat":"Frekans ve annualization tutarlı olmalı.","related":["Sharpe","MaxDD"],"source":"CFA Institute","kind":"Performance Metric","rank":105},{"id":106,"category":"Risk ve Performans Metrikleri","name":"Downside Deviation","short":"Downside Deviation","definition":"Sadece MAR altındaki sapmaları risk olarak ölçer.","formula":"sqrt(mean(min(R_t − MAR,0)^2))","interpretation":"Düşük downside deviation daha az olumsuz oynaklık demektir.","bands":[{"label":"Yorum","text":"Benchmark/stratejiye göre düşük olması olumlu."}],"advantages":["Asimetrik risk için iyi"],"disadvantages":["MAR seçimine hassas"],"suitable":"Portföyler","caveat":"Az downside gözlemde kararsız olabilir.","related":["Sortino","MaxDD"],"source":"CFA Institute","kind":"Performance Metric","rank":106},{"id":107,"category":"Risk ve Performans Metrikleri","name":"Maksimum Drawdown","short":"Max Drawdown","definition":"Zirveden sonraki en büyük yüzde sermaye kaybıdır.","formula":"min(NAV_t / RunningPeak_t − 1)","interpretation":"Daha küçük mutlak MaxDD daha iyi sermaye koruması demektir.","bands":[{"label":"Düşük Risk","text":"<10% mutlak."},{"label":"Kontrollü","text":"<15% sık kullanılan kurumsal hedef."},{"label":"Yüksek","text":">25–30%."}],"advantages":["Gerçek yatırımcı acısını ölçer"],"disadvantages":["Tek olay tarihi domine edebilir"],"suitable":"Tüm portföyler","caveat":"Calmar ve recovery ile birlikte bak.","related":["Calmar","Recovery Factor"],"source":"Risk management","kind":"Performance Metric","rank":107},{"id":108,"category":"Risk ve Performans Metrikleri","name":"Calmar Oranı","short":"Calmar Ratio","definition":"CAGR’ı maksimum drawdown’ın mutlak değerine böler.","formula":"CAGR / |Max Drawdown|","interpretation":"Drawdown başına uzun dönem getiri verimliliğidir.","bands":[{"label":"Zayıf","text":"<0.5"},{"label":"Makul","text":"0.5–1"},{"label":"İyi","text":"1–2"},{"label":"Güçlü","text":">2"}],"advantages":["Drawdown odaklı sezgisel"],"disadvantages":["Tek MaxDD olayına hassas"],"suitable":"Mutlak getiri/hedge fund","caveat":"Birkaç yıllık track record daha anlamlı.","related":["CAGR","MaxDD"],"source":"Performance analysis","kind":"Performance Metric","rank":108},{"id":109,"category":"Risk ve Performans Metrikleri","name":"Recovery Factor","short":"Recovery Factor","definition":"Toplam/net kârı maksimum parasal drawdown’a böler.","formula":"Net Profit / |Maximum Drawdown Amount|","interpretation":"En büyük sermaye kaybına göre ne kadar kâr üretildiğini gösterir.","bands":[{"label":"Zayıf","text":"<1"},{"label":"Makul","text":"1–1.5"},{"label":"İyi","text":"1.5–2"},{"label":"Güçlü","text":">2"}],"advantages":["Trading sistemlerinde pratik"],"disadvantages":["Dönem seçimine hassas"],"suitable":"Trading sistemleri","caveat":"Time-under-water ayrıca incelenmeli.","related":["MaxDD","Calmar"],"source":"Trading performance","kind":"Performance Metric","rank":109},{"id":110,"category":"Risk ve Performans Metrikleri","name":"Tracking Error","short":"Tracking Error","definition":"Portföy ile benchmark aktif getiri farkının volatilitesidir.","formula":"StdDev(R_p − R_b)","interpretation":"Yüksek TE daha agresif aktif risk demektir.","bands":[{"label":"Yorum","text":"İyi/kötü değil; aktif risk bütçesiyle kıyas."}],"advantages":["Aktif risk bütçesi"],"disadvantages":["Benchmarka bağımlı"],"suitable":"Benchmarklı fonlar","caveat":"IR ile birlikte yorumla.","related":["Information Ratio"],"source":"CFA Institute","kind":"Performance Metric","rank":110},{"id":111,"category":"Risk ve Performans Metrikleri","name":"Upside Capture","short":"Upside Capture","definition":"Benchmark pozitif dönemlerde portföyün benchmark getirisinin yüzde kaçını yakaladığını ölçer.","formula":"Portfolio up-market return / Benchmark up-market return ×100","interpretation":"100 üzeri yükseliş dönemlerinde benchmark üstü katılım.","bands":[{"label":"Güçlü","text":">100%; downside capture da kontrol edilmeli."}],"advantages":["Rejim davranışını gösterir"],"disadvantages":["Az up-period gözleminde kararsız"],"suitable":"Fonlar","caveat":"Tek başına yüksek olması yeterli değildir.","related":["Downside Capture"],"source":"Performance analysis","kind":"Performance Metric","rank":111},{"id":112,"category":"Risk ve Performans Metrikleri","name":"Downside Capture","short":"Downside Capture","definition":"Benchmark negatifken portföyün düşüşün ne kadarını yaşadığını ölçer.","formula":"Portfolio down-market return / Benchmark down-market return ×100","interpretation":"100 altı daha iyi downside protection demektir.","bands":[{"label":"Güçlü","text":"<100%"},{"label":"Çok Güçlü","text":"<70–80%; mandate’e göre."}],"advantages":["Defansif performansı ölçer"],"disadvantages":["Az bear-period gözleminde kararsız"],"suitable":"Fonlar","caveat":"Upside capture ile birlikte bak.","related":["Upside Capture","MaxDD"],"source":"Performance analysis","kind":"Performance Metric","rank":112},{"id":113,"category":"Risk ve Performans Metrikleri","name":"Profit Factor","short":"Profit Factor","definition":"Toplam brüt kârı toplam brüt zarara böler.","formula":"Gross Profit / |Gross Loss|","interpretation":"1 üzeri sistem brüt bazda kârlıdır.","bands":[{"label":"Kârsız","text":"<1"},{"label":"Zayıf","text":"1–1.25"},{"label":"Makul","text":"1.25–1.5"},{"label":"İyi","text":"1.5–2"},{"label":"Güçlü","text":">2"}],"advantages":["Trading sistemi için anlaşılır"],"disadvantages":["İşlem sırası/drawdown’u görmez"],"suitable":"Trading stratejileri","caveat":"Komisyon/slippage dahil et.","related":["Win Rate","Payoff Ratio"],"source":"Trading performance","kind":"Performance Metric","rank":113},{"id":114,"category":"Risk ve Performans Metrikleri","name":"Payoff Ratio","short":"Payoff Ratio","definition":"Ortalama kazanan işlemi ortalama kaybedene oranlar.","formula":"Average Win / |Average Loss|","interpretation":"Düşük win-rate yüksek payoff ile kârlı olabilir.","bands":[{"label":"Yorum","text":">1 kazananların ortalama kayıptan büyük olduğunu gösterir."}],"advantages":["Expectancy’yi açıklar"],"disadvantages":["Tail loss’u görmez"],"suitable":"Trading stratejileri","caveat":"Win rate ile birlikte bak.","related":["Win Rate","Expectancy"],"source":"Trading performance","kind":"Performance Metric","rank":114},{"id":115,"category":"Risk ve Performans Metrikleri","name":"Expectancy / Trade","short":"Expectancy","definition":"Bir işlemin uzun dönem ortalama beklenen sonucudur.","formula":"WinRate×AvgWin − LossRate×|AvgLoss|","interpretation":"Pozitif expectancy işlem başına edge olduğunu gösterir.","bands":[{"label":"İyi","text":">0, maliyet sonrası stabil."},{"label":"Kötü","text":"≤0"}],"advantages":["Edge’i doğrudan ölçer"],"disadvantages":["Örneklem/rejim değişimine hassas"],"suitable":"Trading stratejileri","caveat":"Trade count ve tail dağılımı önemli.","related":["Profit Factor","Payoff Ratio"],"source":"Trading performance","kind":"Performance Metric","rank":115}];
